// Context-only Match Frame / Project reveal, executed by the actual pinned engine.
use filmcraft_project::*;use filmcraft_time::{Tick,TimeRange};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn main()->Result<(),Box<dyn std::error::Error>>{
 let mut s=filmcraft_engine::Session::default();s.execute("file.openDemoProject",json!({}))?;let sequence=s.state.active_sequence.unwrap();let p=std::sync::Arc::make_mut(&mut s.project);let media=p.items.values().find(|i|i.as_media().is_some()).unwrap().id;let sub=p.add_item("Restricted",Label::Rose,ItemKind::Subclip{parent:media,range:TimeRange::new(Tick(100),Tick(100000000000)),restrict_trims:true},None);
 let q=p.sequence_mut(sequence).unwrap();for t in q.video_tracks.iter_mut().chain(q.audio_tracks.iter_mut()){for c in &mut t.items{c.start=Tick(0);c.duration=Tick(10*254016000000);c.source_in=Tick(100*254016000000);c.speed=0.75;c.frame_hold=None;c.reverse=false;}if t.items.len()>1{t.items.truncate(1)}}for t in q.video_tracks.iter_mut().skip(2){t.items.clear();}for t in q.audio_tracks.iter_mut().skip(1){t.items.clear();}
 let first=q.video_tracks[0].items[0].id;let top=q.video_tracks[1].items[0].id;let audio=q.audio_tracks[0].items[0].id;let v1=q.video_tracks[0].id;let at=q.audio_tracks[0].id;
 q.video_tracks[1].locked=true;q.video_tracks[1].enabled=false;q.video_tracks[1].muted=true;let it=&mut q.video_tracks[1].items[0];it.enabled=false;it.duration=Tick(8*254016000000);it.source_in=Tick(300*254016000000);it.speed=-1.5;it.reverse=true;q.audio_tracks[0].items[0].duration=Tick(20*254016000000);q.audio_tracks[0].items[0].frame_hold=Some(Tick(27));
 let base=s.project.clone();let mut profiles=vec![];for pi in 0..6{let mut p=base.clone();let q=std::sync::Arc::make_mut(&mut p).sequence_mut(sequence).unwrap();let top=&mut q.video_tracks[1].items[0];if pi==1{top.item=ItemId(u64::MAX);}if pi==2{top.item=sub;}if pi==3{top.frame_hold=Some(Tick(9007199254740997));}if pi==4{top.speed=0.;top.source_in=Tick(0);}if pi==5{q.video_tracks[0].items.clear();q.video_tracks[1].items.clear();}profiles.push(p);}
 let choices:Vec<Value>=vec![json!({}),json!({"clip":first.0}),json!({"clip":top.0}),json!({"clip":999999}),json!({"clips":[]}),json!({"clips":[audio.0]}),json!({"clips":[999999,first.0]}),json!({"item":media.0}),json!({"item":sub.0}),json!({"item":u64::MAX})];let mut cases=vec![];
 for(pi,project)in profiles.iter().enumerate(){for active in [Some(sequence),None]{for time in [0,3*254016000000,8*254016000000,9*254016000000,15*254016000000,22*254016000000,-10]{for selected in [vec![],vec![first],vec![ClipId(999999),first],vec![audio]]{if active.is_none()&&(time!=0||!selected.is_empty()){continue}for command in ["sequence.matchFrame","clip.revealInProject","sequence.revealInProject"]{for params in &choices{
 s.project=project.clone();s.history.undo.clear();s.history.redo.clear();s.events.clear();s.state.active_sequence=active;s.state.source_item=Some(media);s.state.source_playhead=Tick(55);s.state.selection=selected.clone();s.state.project_selection=vec![sub,ItemId(999999),sub];s.state.playheads.clear();s.state.playheads.insert(sequence,Tick(time));s.state.selection_follows_playhead=true;s.state.targeting.clear();if pi%3!=0{s.state.targeting.insert(sequence,filmcraft_engine::Targeting{targeted:if pi%3==1{vec![]}else{vec![v1,at]},..Default::default()});}
 let mut context=json!({"activeSequence":active,"sourceItem":s.state.source_item,"sourcePlayhead":55,"playhead":s.playhead().0,"selection":selected,"projectSelection":s.state.project_selection,"selectionFollowsPlayhead":true});if pi%3!=0{context["targetedTrackIds"]=json!(s.state.targeting[&sequence].targeted);}
 let r=s.execute(command,params.clone());let after=serde_json::to_value(s.project.as_ref())?;let events:Vec<_>=s.events.iter().filter_map(|e|match e{filmcraft_engine::Event::OpenSource(id)=>Some(json!({"type":"openSource","item":id.0})),filmcraft_engine::Event::RevealInProject(id)=>Some(json!({"type":"revealInProject","item":id.0})),_=>None}).collect();
 cases.push(json!({"profile":pi,"command":command,"params":params,"context":context,"ok":r.is_ok(),"result":r.ok(),"afterContext":{"activeSequence":s.state.active_sequence,"sourceItem":s.state.source_item,"sourcePlayhead":s.state.source_playhead,"playhead":s.playhead(),"playheadFrames":s.sequence_rate().frame_at(s.playhead()),"selection":s.state.selection,"projectSelection":s.state.project_selection},"events":events,"afterSha256":format!("{:x}",Sha256::digest(serde_json::to_vec(&after)?)),"undo":s.history.undo.len()}));
 }}}}}}
 let projects:Vec<_>=profiles.iter().map(|p|p.as_ref()).collect();std::fs::write(std::env::args().nth(1).ok_or("output required")?,serde_json::to_vec(&json!({"sourceCommit":"5231852443363f001c3f6b396dd9b1e6461ae2be","projects":projects,"cases":cases}))?)?;Ok(())
}
